import { API_BASE_URL } from '../config/api';

export interface HealthSummary {
  steps: number;
  stepsTarget: number;
  calories: number;
  caloriesTarget: number;
  sleepHours: number;
  sleepTarget: number;
  weeklySteps: number[];
}

export async function fetchHealthSummary(): Promise<HealthSummary> {
  const response = await fetch(`${API_BASE_URL}/health/today`);
  if (!response.ok) throw new Error(`Health failed with status ${response.status}`);
  return (await response.json()) as HealthSummary;
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { View, Text, StyleSheet, SafeAreaView, ActivityIndicator, ScrollView } from 'react-native';
import { fetchHealthSummary, type HealthSummary } from '../services/health';

const colors = {
  accent: '#f05039',
  success: '#4ade80',
  info: '#60a5fa',
  bg: '#0f120e',
  danger: '#ff6b5e',
  muted: '#8a8f8a',
  text: '#f5f5f0',
  textSoft: '#d8dbd4',
  border: '#242a24',
}

const DAYS = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];

function Ring({ label, value, target, color }: { label: string; value: number; target: number; color: string }): JSX.Element {
  const pct = target > 0 ? Math.min(1, value / target) : 0;
  const circumference = 2 * Math.PI * 40;
  return (
    <View style={styles.ringWrap} accessibilityLabel={`${label}: ${value} of ${target}`}>
      <View style={styles.ringTrack}>
        <View style={[styles.ringFill, { borderColor: color, transform: [{ rotate: `${pct * 360}deg` }] }]} />
        <View style={styles.ringCenter}>
          <Text style={styles.ringValue}>{Math.round(pct * 100)}%</Text>
        </View>
      </View>
      <Text style={styles.ringLabel}>{label}</Text>
    </View>
  );
}

export function HealthDashboardScreen(): JSX.Element {
  const [health, setHealth] = useState<HealthSummary | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

    const load = useCallback(async () => {

    try {
      const data = await fetchHealthSummary();
      setHealth(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load health data.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const maxWeek = useMemo(() => (health ? Math.max(...health.weeklySteps, 1) : 1), [health]);

  return (
    <SafeAreaView style={styles.safe}>
      {loading && <ActivityIndicator color="{colors.accent}" style={styles.center} />}
      {!loading && error && <Text style={styles.error}>{error}</Text>}
      {!loading && !health && !error && <Text style={styles.empty}>No health data yet.</Text>}
      {!loading && health && (
        <ScrollView contentContainerStyle={styles.content}>
          <Text style={styles.title}>Today</Text>
          <View style={styles.rings}>
            <Ring label="Steps" value={health.steps} target={health.stepsTarget} color="{colors.accent}" />
            <Ring label="Calories" value={health.calories} target={health.caloriesTarget} color="{colors.success}" />
            <Ring label="Sleep" value={health.sleepHours} target={health.sleepTarget} color="{colors.info}" />
          </View>
          <Text style={styles.section}>This week</Text>
          <View style={styles.chart}>
            {health.weeklySteps.map((steps, i) => (
              <View key={i} style={styles.barCol} accessibilityLabel={`Day ${DAYS[i]}: ${steps} steps`}>
                <View style={[styles.bar, { height: Math.max(4, (steps / maxWeek) * 120) }]} />
                <Text style={styles.barLabel}>{DAYS[i]}</Text>
              </View>
            ))}
          </View>
        </ScrollView>
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  center: { marginTop: 40 },
  error: { color: colors.danger, textAlign: 'center', marginTop: 24 },
  empty: { color: colors.muted, textAlign: 'center', marginTop: 24 },
  content: { padding: 20 },
  title: { fontSize: 22, fontWeight: '700', color: colors.text, marginBottom: 16 },
  section: { fontSize: 16, fontWeight: '600', color: colors.textSoft, marginTop: 24, marginBottom: 12 },
  rings: { flexDirection: 'row', justifyContent: 'space-around' },
  ringWrap: { alignItems: 'center', gap: 8 },
  ringTrack: { width: 96, height: 96, borderRadius: 48, borderWidth: 10, borderColor: colors.border, alignItems: 'center', justifyContent: 'center', position: 'relative', overflow: 'hidden' },
  ringFill: { position: 'absolute', top: -10, left: -10, right: -10, bottom: -10, borderRadius: 48, borderWidth: 10, borderLeftColor: 'transparent', borderBottomColor: 'transparent', borderRightColor: 'transparent', borderTopColor: 'transparent' },
  ringCenter: { alignItems: 'center' },
  ringValue: { color: colors.text, fontWeight: '700' },
  ringLabel: { color: colors.muted, fontSize: 12 },
  chart: { flexDirection: 'row', alignItems: 'flex-end', gap: 8, height: 140 },
  barCol: { flex: 1, alignItems: 'center', justifyContent: 'flex-end' },
  bar: { width: '70%', backgroundColor: colors.accent, borderRadius: 3, minHeight: 4 },
  barLabel: { color: colors.muted, fontSize: 10, marginTop: 6 },
});
